import type { Room } from "./game";
import type { StoryEnding } from "./story";
import { fallbackAchievement, type Achievement } from "./achievements.ts";
import { itemsUsed } from "./inventory.ts";

export type ActionOutcome = {
  success: boolean;
  roll: number;
  bonus: number;
  creativity: number;
  masterstroke: boolean;
  difficulty: number;
  heartsLost: number;
  reward: string | null;
  usedItems: string[];
  narration: string;
  mode: "ai" | "scripted";
  achievement?: Achievement | null;
  /** Optional, generated by the existing final-room judge call. */
  epilogue?: string;
  storyEnding?: StoryEnding;
  artTicket?: string;
};

function bonusForAction(action: string, inventory: readonly string[]): number {
  return itemsUsed(action, inventory).length ? 2 : 0;
}

export function resolveAction(room: Room, action: string, inventory: readonly string[], roll: number, creativity = 0): ActionOutcome {
  const safeRoll = Math.max(1, Math.min(20, Math.floor(roll)));
  const wit = Math.max(0, Math.min(5, Math.floor(creativity)));
  const bonus = bonusForAction(action, inventory) + wit;
  const masterstroke = wit === 5;
  const success = masterstroke || safeRoll + bonus >= room.difficulty;
  return {
    success,
    roll: safeRoll,
    bonus,
    creativity: wit,
    masterstroke,
    difficulty: room.difficulty,
    heartsLost: success ? 0 : 1,
    reward: success ? room.reward : null,
    usedItems: itemsUsed(action, inventory),
    narration: room.title === "The Frightened Guard" && success &&
      /\b(attack|stab|slash|kill|hit|punch|fight|shoot|strike|smash)\b/i.test(action)
      ? "Spoon drops his sword and flees. The bell tower stands open, but you have lost a potential friend."
      : fallbackNarration(room, success),
    mode: "scripted",
    achievement: fallbackAchievement(action, room.title, success, 0)
  };
}

export function fallbackNarration(room: Room, success: boolean): string {
  const happy: Record<string, string> = {
    "The Old Stone Bridge": "Boggle blinks, checks a rulebook that is clearly blank, and stamps your imaginary paperwork. 'Regrettably, that counts. You may pass.'",
    "The Library of Accusations": "The books argue furiously among themselves. Madame Index declares your case 'disturbingly persuasive' and waves you onward.",
    "The Dragon's Tax Office": "Emberfax sighs so hard the furniture smoulders. 'A technically valid exemption. Disgusting.' You escape with the treasure.",
    "The Upside-Down Tavern": "Against all reasonable expectations, your plan works. The bartender reluctantly offers you a gravity voucher.",
    "The Sphinx's Day Off": "The sphinx laughs despite herself. 'Fine. That was new.' She lets you through with a theatrical bow.",
    "The Wizard's Return": "Grumble tries to look displeased, but hands over a medal. He insists it is a clerical error.",
    "The Onion Rebellion": "The onion delegates confer in tears. A peace treaty is signed, and passage is yours.",
    "The Cheese Oracle": "Brie pauses, impressed. 'That is annoyingly insightful.' A cheesy prophecy is bestowed.",
    "The Hungry King": "The king stares, takes a bite, then demands that your masterpiece be entered into the royal archives.",
    "The Escaped Painting": "Lady Varnish sweeps back into her frame with an extravagant bow. The gallery applauds using only its elbows.",
    "The Clockwork Skeleton": "Percy snaps his bones into the right slots and dances a victory jig, shaking loose one ceremonial rib.",
    "The Forbidden Exhibit": "The crown finally falls quiet. Curator Nocturne grants you a midnight pass and swears never to exhibit your methods.",
    "A Whale with Stage Fright": "Nimbus takes a deep breath, strikes a pose, and rises into the stars. You receive a skywhale ticket.",
    "The Thundercloud Tollbooth": "Thunderpuff grumbles, but accepts your outrageous toll. The storm parts with a polite rumble.",
    "The Moon Station": "The passengers make it across just in time. Conductor Crescent awards you a medal under moonlight.",
    "The Frightened Guard": "Spoon lowers his sword and unlocks the tower. He whispers a warning about something sleeping below.",
    "The Whispering Stair": "You steady the cracked gears long enough to read the inscription: willing promises can replace stolen names.",
    "The Bell and the Keeper": "Elowen listens as your audacious plan takes shape. The tower shudders, awaiting its final fate.",
    "The Drowsy Harbour": "Pip's lantern catches your solution and flickers brightly enough for the nearest fishing boat to find the harbour wall. The otter cheers, though the missing sunrise still needs saving.",
    "The Singing Spiral Stair": "Mallow folds her wings and recognises the morning note in your solution. The moon-moth lets you climb toward the lens, humming along behind you.",
    "The Sunrise Lens": "Solbit listens to your promise. The small sun takes courage and leaps from its glass prison, turning Brinewatch's cold horizon gold.",
    "The Beekeeper's Workshop": "Tock's copper bees begin buzzing again, delighted by your odd but effective idea. Their tiny wings mark a safe path to the orchard's damaged apple.",
    "The Upside-Down Apple": "Nutmeg watches your invention halt the backward gears. The clockwork apple shivers back into balance and reveals a hidden route to the great tree.",
    "The Heartwood Clock": "Professor Caw caws his approval as the sunflower clock ticks toward spring. The brass petals unfold, and warm light travels through the orchard.",
    "The Cold Dragon Oven": "Crumpet's little oven roars warmly back to life, filling the bakery with the scent of fresh bread. Unfortunately, the dough has noticed too.",
    "The Runaway Dough": "Doughbert stops long enough to hear your plan. Crumpet rescues the yeast, and the once-rebellious loaf agrees to help prepare the giant's dinner.",
    "The Hungry Hill": "Grumble considers your astonishing feast and accepts it with a pleased rumble. The bakery is safe, and the giant asks whether the position of official taster is available."
  };
  const sad: Record<string, string> = {
    "The Old Stone Bridge": "Boggle is unmoved. He charges you a toll in dignity instead. You squeeze past, one heart lighter.",
    "The Library of Accusations": "The books shout 'OBJECTION!' in unison. A heavy dictionary strikes your foot as you escape.",
    "The Dragon's Tax Office": "The dragon issues a fiery penalty notice. Your escape is technically successful, but painfully expensive.",
    "The Upside-Down Tavern": "The room spins. A flying tankard clips your shoulder. The bartender adds your name to the complaints book.",
    "The Sphinx's Day Off": "The sphinx yawns. 'I've seen better from a sleeping turnip.' A trapdoor drops you into the next room.",
    "The Wizard's Return": "Grumble turns your eyebrows purple. It is mostly harmless, except to your pride and one heart.",
    "The Onion Rebellion": "The onions boo in several dialects. You retreat through a cloud of weaponised tears.",
    "The Cheese Oracle": "Brie offers only a cryptic snort. A wheel of cheddar rolls over your foot on the way out.",
    "The Hungry King": "The king declares the dinner a national embarrassment. The royal guards usher you away with a stern look.",
    "The Escaped Painting": "Lady Varnish flees behind another statue. You trip over a velvet rope, losing a heart as you scramble onward.",
    "The Clockwork Skeleton": "Percy reassembles himself as a very confused chair. You escape with bruised toes and one fewer heart.",
    "The Forbidden Exhibit": "The crown echoes your plan so loudly that the curator faints. You stagger away, ears ringing.",
    "A Whale with Stage Fright": "Nimbus panics and sneezes a cloud at you. The train eventually leaves, but you lose a heart.",
    "The Thundercloud Tollbooth": "Thunderpuff sends a very personal rain shower after you. You limp onward, one heart lighter.",
    "The Moon Station": "The drifting platform clips your boots. You make a messy landing while losing one precious heart.",
    "The Frightened Guard": "Spoon panics and flees. You slip into the tower through a broken side gate, bruised but alive.",
    "The Whispering Stair": "The gears splinter, costing you a heart. A broken cog still reveals that the bell keeps something asleep.",
    "The Bell and the Keeper": "The bell refuses your plan and takes another memory. You stumble from the tower as Elowen holds the ward.",
    "The Drowsy Harbour": "The lantern sputters instead of shining. Pip is worried but points you toward the lighthouse stair. You'll have to find the lost morning without a guiding flame.",
    "The Singing Spiral Stair": "Mallow shakes her fuzzy head. The wrong song echoes through the stairwell as you squeeze through an emergency hatch toward the lens.",
    "The Sunrise Lens": "Solbit remains trapped. Brinewatch survives another dark hour, but the sea rises, and the villagers will have to try again tomorrow.",
    "The Beekeeper's Workshop": "The copper bees refuse to cooperate. Tock sighs and gives you directions to the apple, where the orchard's clockwork trouble is getting worse.",
    "The Upside-Down Apple": "The apple refuses your plan and turns another tick backward. Nutmeg reveals a narrow tunnel into the heartwood before winter can close it.",
    "The Heartwood Clock": "Professor Caw squawks as the clock stalls again. Frost creeps across the brass petals; the orchard will need another improbable saviour.",
    "The Cold Dragon Oven": "The oven coughs out a pathetic curl of smoke. Crumpet points at the runaway dough, hoping you can retrieve the bakery's last yeast before it escapes.",
    "The Runaway Dough": "Doughbert bounces away with the last yeast. Crumpet goes pale beneath the flour, and you must face the hungry giant without a proper loaf.",
    "The Hungry Hill": "Grumble's stomach roars louder than your plan can satisfy. The gentle giant backs away hungry, and the villagers begin counting their remaining biscuits."
  };
  const narration = (success ? happy[room.title] : sad[room.title]) ??
    (success ? "Somehow, your audacity works. The path opens." : "Your attempt goes sideways. You stagger onward, minus one heart.");
  return room.echo ? narration + " " + room.echo : narration;
}
